import { useEffect, useState, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Wifi, Download, Upload, Activity, MapPin, Server } from 'lucide-react';
import { ResponsiveContainer, AreaChart, Area, XAxis, Tooltip } from 'recharts';

function SpeedChecker() {
  const [download, setDownload] = useState(0);
  const [upload, setUpload] = useState(0);
  const [ping, setPing] = useState(0);
  const [testing, setTesting] = useState(false);
  const [history, setHistory] = useState([]);

  const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:5000';

  const runTest = useCallback(async () => {
    try {
      console.log('=== SPEED TEST STARTED ===');
      setTesting(true);
      setDownload(0);
      setUpload(0);
      setPing(0);
      setHistory([]);

      // Stage 1: Ping (RTT)
      console.log('Calling backend ping...');
      const pingResp = await fetch(`${API_BASE}/api/test-speed`, {
        cache: 'no-store',
        headers: {
          'Cache-Control': 'no-cache, no-store, must-revalidate',
        },
      });

      if (!pingResp.ok) {
        throw new Error(`Ping failed: ${pingResp.status}`);
      }

      const pingData = await pingResp.json();
      const pingResult = pingData.ping || 0;

      // Stage 2: Download (browser measures actual received bytes over time)
      const isLocalhost = API_BASE.includes('localhost') || API_BASE.includes('127.0.0.1');
      const downloadDurationMs = isLocalhost ? 8000 : 15000; // ~8-15s to stabilize

      console.log(`Running download stage for ~${downloadDurationMs}ms...`);

      // We download in repeated requests so we can cap by time (like fast.com).
      const downloadChunkSize = isLocalhost ? 2 * 1024 * 1024 : 5 * 1024 * 1024; // 2-5MB per request
      const downloadStart = performance.now();

      let receivedBytes = 0;
      let lastSampleBytes = 0;
      let lastSampleTime = performance.now();

      while (performance.now() - downloadStart < downloadDurationMs) {
        const remainingMs = downloadDurationMs - (performance.now() - downloadStart);
        const downloadResp = await fetch(`${API_BASE}/api/download?size=${downloadChunkSize}`, {
          cache: 'no-store',
        });
        if (!downloadResp.ok) throw new Error(`Download failed: ${downloadResp.status}`);

        const reader = downloadResp.body?.getReader();
        if (!reader) throw new Error('Streaming download not supported by this browser');

        while (true) {
          const now = performance.now();
          if (now - downloadStart >= downloadDurationMs) break;

          const { value, done } = await reader.read();
          if (done) break;
          if (value) receivedBytes += value.byteLength;

          if (now - lastSampleTime >= 1000) {
            const intervalBytes = receivedBytes - lastSampleBytes;
            const intervalSeconds = (now - lastSampleTime) / 1000;
            const mbps = (intervalBytes * 8) / intervalSeconds / 1000000;
            setHistory((prev) => [
              ...prev,
              {
                time: prev.length,
                speed: Math.round(mbps),
              },
            ]);
            setDownload(Math.round(mbps));
            lastSampleBytes = receivedBytes;
            lastSampleTime = now;
          }
        }

        if (remainingMs < 200) break;
      }

      const downloadEnd = performance.now();
      const downloadSeconds = Math.max((downloadEnd - downloadStart) / 1000, 0.001);
      const downloadMbpsTotal = (receivedBytes * 8) / downloadSeconds / 1000000;
      const downloadSpeed = Math.max(downloadMbpsTotal, 0);

      setDownload(Math.round(downloadSpeed));
      setPing(pingResult);

      // Stage 3: Upload (use backend's received-bytes duration for accuracy)
      console.log(`Running upload stage...`);

      const uploadChunkSize = isLocalhost ? 128 * 1024 : 256 * 1024; // 128-256KB
      const chunk = new Uint8Array(uploadChunkSize);

      const uploadStart = performance.now();
      let lastServerSpeed = 0;

      while (performance.now() - uploadStart < downloadDurationMs) {
        const resp = await fetch(`${API_BASE}/api/upload-large`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/octet-stream',
            'Cache-Control': 'no-cache',
          },
          body: chunk,
        });

        if (!resp.ok) throw new Error(`Upload failed: ${resp.status}`);

        const data = await resp.json();
        if (typeof data.speed === 'number') {
          lastServerSpeed = data.speed;
          setUpload(Math.round(lastServerSpeed));
        }
      }

      setUpload(Math.round(lastServerSpeed));
      setPing(pingResult);
      setTesting(false);

      console.log(
        `Ping: ${pingResult}ms, Download: ${Math.round(downloadSpeed)}Mbps, Upload: ${Math.round(uploadSpeed)}Mbps`,
      );
      console.log('=== SPEED TEST COMPLETED ===');
    } catch (err) {
      console.error('Speed test error:', err);
      setTesting(false);
      alert(
        `Speed test failed: ${err.message}\n\nMake sure backend server is running on port 5000`,
      );
    }
  }, [API_BASE]);

  useEffect(() => {
    // Auto-run test on component mount
    const timer = setTimeout(() => runTest(), 500);
    return () => clearTimeout(timer);
  }, [runTest]);

  return (
    <div className="main-bg">
      <div className="container py-4">
        {/* HEADER */}
        <div className="topbar">
          <div className="d-flex align-items-center gap-3">
            <img
              src="/logo.png"
              alt="Speed Checker Logo"
              className="logo-img"
              style={{ height: '50px', width: 'auto' }}
            />
          </div>

          <button className="run-btn" onClick={runTest} disabled={testing}>
            {testing ? 'TESTING...' : 'RUN TEST'}
          </button>
        </div>

        {/* TOP CARDS */}
        <div className="row g-4 mt-1">
          <div className="col-6 col-lg-3">
            <MiniCard title="Download" value={`${download} Mbps`} icon={<Download />} />
          </div>

          <div className="col-6 col-lg-3">
            <MiniCard title="Upload" value={`${upload} Mbps`} icon={<Upload />} />
          </div>

          <div className="col-6 col-lg-3">
            <MiniCard title="Ping" value={`${ping} ms`} icon={<Activity />} />
          </div>

          <div className="col-6 col-lg-3">
            <MiniCard title="Status" value={testing ? 'Testing' : 'Stable'} icon={<Wifi />} />
          </div>
        </div>

        {/* MAIN PANEL */}
        <div className="glass-panel mt-4">
          {/* SPEED DISPLAY */}
          <motion.div
            key={download}
            initial={{ scale: 0.8, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            className="speed-display"
          >
            <h1 className="speed-value">{download}</h1>
            <div className="speed-unit">Mbps</div>
          </motion.div>

          {/* GRAPH */}
          <div className="chart-box">
            <ResponsiveContainer width="100%" height={300}>
              <AreaChart data={history}>
                <defs>
                  <linearGradient id="colorSpeed" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#00f7ff" stopOpacity={0.8} />
                    <stop offset="95%" stopColor="#00f7ff" stopOpacity={0} />
                  </linearGradient>
                </defs>

                <XAxis dataKey="time" stroke="#6ecfff" />
                <Tooltip />

                <Area
                  type="monotone"
                  dataKey="speed"
                  stroke="#00f7ff"
                  fill="url(#colorSpeed)"
                  strokeWidth={3}
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* BOTTOM INFO */}
        <div className="row g-4 mt-1">
          <div className="col-md-4">
            <InfoCard title="Server" value="Local" icon={<Server />} />
          </div>

          <div className="col-md-4">
            <InfoCard title="Location" value="Your PC" icon={<MapPin />} />
          </div>

          <div className="col-md-4">
            <InfoCard title="Connection" value="Accurate" icon={<Wifi />} />
          </div>
        </div>

        {/* FOOTER */}
        <footer className="footer-section">
          <div className="footer-links">
            <Link to="/privacy-policy" className="footer-link">
              Privacy Policy
            </Link>
            <span className="separator">|</span>
            <Link to="/terms-of-service" className="footer-link">
              Terms of Service
            </Link>
            <span className="separator">|</span>
            <Link to="/disclaimer" className="footer-link">
              Disclaimer
            </Link>
            <span className="separator">|</span>
            <Link to="/about-us" className="footer-link">
              About Us
            </Link>
            <span className="separator">|</span>
            <Link to="/cookie-policy" className="footer-link">
              Cookie Policy
            </Link>
          </div>
          <p className="footer-copyright">
            © 2026 Speed Checker. All rights reserved. Powered by Speed Checker
          </p>
        </footer>
      </div>
    </div>
  );
}

function MiniCard({ title, value, icon }) {
  return (
    <div className="mini-card">
      <div className="mini-icon">{icon}</div>
      <div className="mini-title">{title}</div>
      <div className="mini-value">{value}</div>
    </div>
  );
}

function InfoCard({ title, value, icon }) {
  return (
    <div className="info-card">
      <div className="info-icon">{icon}</div>
      <div className="info-title">{title}</div>
      <div className="info-value">{value}</div>
    </div>
  );
}

export default SpeedChecker;
